import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.9yf7n3zg.js";const u=JSON.parse('{"title":"Mood board","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mood-board.md","filePath":"guide/mood-board.md","lastUpdated":1792685126000}'),n={name:"guide/mood-board.md"};function s(d,e,i,h,c,l){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="mood-board" tabindex="-1">Mood board <a class="header-anchor" href="#mood-board" aria-label="Permalink to &quot;Mood board&quot;">​</a></h1><p>The mood board is a free board for what a story feels like: cards you type anywhere, pictures, notes you already keep, web pages, gathered in groups and joined by lines. Nothing on it is prose, and nothing on it is ordered; put things where they make sense to you.</p><p>The board is a file of its own, <code>Mood.canvas</code> in the story&#39;s author data folder. It is a <a href="https://jsoncanvas.org" target="_blank" rel="noreferrer">JSON Canvas</a>, the same file Obsidian&#39;s Canvas writes, so you can open the board in Obsidian and change it there; Leathercase reads it back when you return.</p><h2 id="opening-the-board" tabindex="-1">Opening the board <a class="header-anchor" href="#opening-the-board" aria-label="Permalink to &quot;Opening the board&quot;">​</a></h2><p>Open a story, then pick <strong>Mood Board</strong> under the story&#39;s name in the sidebar, just after the beat board. You can also type &quot;Mood board&quot; in the command palette (<code>Ctrl/Cmd+K</code>). It has no key of its own; you can give it one in <code>keybindings.json</code>.</p><p>The board opens fitted to what it holds, never so small that a card can&#39;t be read. Drag the empty board to move around, and use the wheel to zoom. <code>F</code> shows everything; <code>+</code> and <code>-</code> zoom in and out.</p><p>The line at the top of the view says what the board holds, for example <code>8 things · 1 group · 3 lines</code>.</p><h2 id="cards" tabindex="-1">Cards <a class="header-anchor" href="#cards" aria-label="Permalink to &quot;Cards&quot;">​</a></h2><p>Double-click anywhere on the board to write a card there, or press <code>N</code> to write one near the middle of what you see. The card is one field, typed as markdown:</p><ul><li>The first line is the card&#39;s title. It may start with <code>#</code> as a heading.</li><li>Everything after it is the card&#39;s text, in markdown: <strong>bold</strong>, <em>italic</em>, lists, quotes, <code>[[links]]</code>, <code>==highlights==</code>.</li><li>A <code>#tag</code> anywhere in the card becomes a tag, as on the <a href="/guide/guide/beat-board">beat board</a>.</li><li><code>Ctrl/Cmd+Enter</code> or clicking away saves the card; <code>Esc</code> puts it back.</li></ul><p>While you type, the card shows its markdown. Once it is saved, it shows the markdown rendered.</p><p>To write a card again, double-click it, or pick it and press <code>Enter</code>, or use <strong>Write</strong> in the side column. A new first line renames the card. Another card&#39;s title is refused.</p><p>Each card is a short note Leathercase keeps for you, under <code>Mood/</code> in the story&#39;s author data folder, named for its title. Read without Leathercase, it is a plain markdown file.</p><h2 id="pictures" tabindex="-1">Pictures <a class="header-anchor" href="#pictures" aria-label="Permalink to &quot;Pictures&quot;">​</a></h2><p>Drop pictures from your file manager onto the board, or paste one with <code>Ctrl/Cmd+V</code>. Leathercase copies each picture into <code>Mood/</code> and puts it on the board in its own proportions. Your original file is not moved.</p><h2 id="notes-and-things-you-already-have" tabindex="-1">Notes, and things you already have <a class="header-anchor" href="#notes-and-things-you-already-have" aria-label="Permalink to &quot;Notes, and things you already have&quot;">​</a></h2><p>From the view&#39;s menu (⋯), <strong>Put a note on the board…</strong> lists the notes of your home: your own notes, the <a href="/guide/guide/writer-board">Writer board</a>&#39;s cards, beat cards. Type to filter, then pick one. It shows on the board with its opening lines.</p><p>A note of yours is only shown: Leathercase never writes into it. <strong>Open</strong> on the note, or a double-click, opens it in the software you write with.</p><h2 id="web-links" tabindex="-1">Web links <a class="header-anchor" href="#web-links" aria-label="Permalink to &quot;Web links&quot;">​</a></h2><p><strong>Add a web link…</strong> in the menu, or paste or drop a web address on the board. Only <code>https</code> addresses go on the board, the ones Leathercase opens in your browser. Leathercase reads the page once, when you add it, for its title, its description and its picture, and keeps them with the board in <code>MoodLinks.json</code>. It never goes online on its own: a link&#39;s card changes only when you press <strong>Read again</strong>. <strong>Open</strong> opens the page in your browser.</p><p>Leathercase only reads pages on the web. It never fetches an address on your own computer or your local network.</p><h2 id="groups-and-lines" tabindex="-1">Groups and lines <a class="header-anchor" href="#groups-and-lines" aria-label="Permalink to &quot;Groups and lines&quot;">​</a></h2><p>Press <code>G</code> with some things picked (shift-click to pick more than one) to put a group around them, or pick <strong>New group</strong> in the menu. A group moves what lies wholly inside it. Rename it with <strong>Rename</strong> in the side column.</p><p>To join two things, pick one and drag the dot on its right edge onto the other. The line runs from the sides that face each other, with an arrow at the end. Click a line to pick it; the side column lets you write what it says, or take it off.</p><h2 id="moving-sizing-and-colours" tabindex="-1">Moving, sizing and colours <a class="header-anchor" href="#moving-sizing-and-colours" aria-label="Permalink to &quot;Moving, sizing and colours&quot;">​</a></h2><p>Drag a card to move it, and drag the small square at its bottom right corner to resize it. With things picked, the side column has:</p><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td>The colour dots</td><td>Colours what is picked, or takes its colour off. These are the canvas&#39;s six colours, which Obsidian shows in its own shades.</td></tr><tr><td><strong>Bring to front</strong></td><td>Draws what is picked above the rest.</td></tr><tr><td><strong>Group</strong></td><td>Puts a group around what is picked.</td></tr><tr><td><strong>Take off the board</strong></td><td>Takes it off the board. A card&#39;s note goes to your system&#39;s trash with it; a picture&#39;s file stays in <code>Mood/</code>.</td></tr></tbody></table><h2 id="undo" tabindex="-1">Undo <a class="header-anchor" href="#undo" aria-label="Permalink to &quot;Undo&quot;">​</a></h2><p>Every change is written at once and named in the strip under the board, with <strong>Undo</strong>. <code>Ctrl/Cmd+Z</code> undoes, <code>Ctrl/Cmd+Shift+Z</code> redoes. Undo puts back both the board and a card&#39;s note. If the file changed in the meantime, in Obsidian for example, Undo writes nothing and says so.</p><h2 id="if-the-board-can-t-be-read" tabindex="-1">If the board can&#39;t be read <a class="header-anchor" href="#if-the-board-can-t-be-read" aria-label="Permalink to &quot;If the board can&#39;t be read&quot;">​</a></h2><p>If <code>Mood.canvas</code> is there but isn&#39;t a board Leathercase can read, the view says so and leaves the file exactly as it is. Open it in Obsidian or a text editor to mend it.</p>',31)])])}const b=o(n,[["render",s]]);export{u as __pageData,b as default};
